import{_ as s,o as i,c as a,a as o}from"./app.Dzj71sBz.js";const k=JSON.parse('{"title":"Notification Hooks Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guides/NOTIFICATION_HOOKS_GUIDE.md","filePath":"guides/NOTIFICATION_HOOKS_GUIDE.md","lastUpdated":1771498270000}'),t={name:"guides/NOTIFICATION_HOOKS_GUIDE.md"};function l(n,e,d,c,r,p){return i(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="notification-hooks-guide" tabindex="-1">Notification Hooks Guide <a class="header-anchor" href="#notification-hooks-guide" aria-label="Permalink to &quot;Notification Hooks Guide&quot;">​</a></h1><p>This repo now includes hook-driven desktop notifications with optional voice alerts.</p><h2 id="what-fires" tabindex="-1">What Fires <a class="header-anchor" href="#what-fires" aria-label="Permalink to &quot;What Fires&quot;">​</a></h2><ul><li><code>Stop</code>: from Rust <code>hook-dispatcher</code> (<code>stop</code> mode), includes profile and failures.</li><li><code>TaskCompleted</code>: from <code>hooks/task-completed.sh</code>.</li><li><code>SessionEnd</code>: from <code>hooks/session-cleanup.sh</code>.</li><li><code>TeammateIdle</code>: from <code>hooks/teammate-idle.sh</code> when idle sentinel is detected.</li></ul><h2 id="main-script" tabindex="-1">Main Script <a class="header-anchor" href="#main-script" aria-label="Permalink to &quot;Main Script&quot;">​</a></h2><ul><li><code>hooks/notify-agent-event.sh</code></li></ul><p>It is best-effort and never fails callers.</p><h2 id="session-complete-voice-contract" tabindex="-1">Session Complete Voice Contract <a class="header-anchor" href="#session-complete-voice-contract" aria-label="Permalink to &quot;Session Complete Voice Contract&quot;">​</a></h2><p>For <code>sessionend</code>, spoken/message output is forced to:</p><p><code>Session Complete - Chat X - &lt;NOTI&gt;</code></p><p>Where:</p><ul><li><code>Chat X</code> is a static per-session label persisted from <code>SESSION_ID</code> mapping.</li><li><code>&lt;NOTI&gt;</code> is the moving topic from latest user prompt, truncated to keep speech near ~5s.</li><li>Topic source is updated by <code>hooks/prompt-submit-guard.sh</code> into <code>.claude/notify-topic.txt</code>.</li></ul><h2 id="spoken-contract-all-events" tabindex="-1">Spoken Contract (All Events) <a class="header-anchor" href="#spoken-contract-all-events" aria-label="Permalink to &quot;Spoken Contract (All Events)&quot;">​</a></h2><p>Voice output is normalized to:</p><p><code>&lt;STATE&gt; - &lt;Agent&gt; says - &lt;NOTI&gt;</code></p><p>Examples:</p><ul><li><code>Stop Issues - Codex says - quality checks reported failures</code></li><li><code>Session Complete - Cursor says - Session Complete - Chat 4 - finalize DAG sync</code></li></ul><h2 id="harness-detection" tabindex="-1">Harness Detection <a class="header-anchor" href="#harness-detection" aria-label="Permalink to &quot;Harness Detection&quot;">​</a></h2><p>Notification subtitle includes harness context. Detection order:</p><ol><li><code>THGENT_HARNESS</code> env var from wrappers/shims.</li><li>Parent process scan (<code>cursor</code>, <code>codex/dex</code>, <code>claude/clode</code>, <code>droid/roid</code>).</li><li>fallback: <code>thegent</code>.</li></ol><h2 id="config-env-vars" tabindex="-1">Config (Env Vars) <a class="header-anchor" href="#config-env-vars" aria-label="Permalink to &quot;Config (Env Vars)&quot;">​</a></h2><ul><li><code>THGENT_NOTIFY_ENABLE=0|1</code> (default <code>1</code>)</li><li><code>THGENT_NOTIFY_DRY_RUN=1</code> prints only, no OS push/voice</li><li><code>THGENT_NOTIFY_COOLDOWN_SEC=&lt;int&gt;</code> dedupe window (default <code>8</code>)</li><li><code>THGENT_NOTIFY_VOICE_MODE=errors|all|off</code> (default <code>errors</code>)</li><li><code>THGENT_NOTIFY_VOICE_NAME=&lt;voice&gt;</code> (macOS <code>say</code> voice, default <code>Samantha</code>)</li></ul><h2 id="platform-backends" tabindex="-1">Platform Backends <a class="header-anchor" href="#platform-backends" aria-label="Permalink to &quot;Platform Backends&quot;">​</a></h2><ul><li>macOS: <code>osascript</code> desktop notification fallback (subtitle+title, then title-only), <code>say</code> voice.</li><li>Linux: <code>notify-send</code>/<code>dunstify</code>, <code>spd-say</code>/<code>espeak</code> voice.</li><li>Windows shells: <code>powershell.exe</code> MessageBox fallback.</li><li>Last resort: terminal bell + stderr line.</li></ul><h2 id="apply-changes" tabindex="-1">Apply Changes <a class="header-anchor" href="#apply-changes" aria-label="Permalink to &quot;Apply Changes&quot;">​</a></h2><p>Reinstall wrappers:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> thegent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install-shims</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Deploy hook dispatcher (if needed):</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/bin/hook-dispatcher</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/bin/hook-dispatcher.bak-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%Y%m%d-%H%M%S</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hooks/hook-dispatcher/target/release/hook-dispatcher</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/bin/hook-dispatcher</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/bin/hook-dispatcher</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div>`,29)])])}const u=s(t,[["render",l]]);export{k as __pageData,u as default};
